const Navbar = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${isScrolled ? 'bg-white shadow-md py-3' : 'bg-transparent py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <div className={`w-10 h-10 rounded-full flex items-center justify-center font-display text-xl font-bold ${isScrolled ? 'bg-[#1a3a34] text-white' : 'bg-white text-[#1a3a34]'}`}>L</div>
          <span className={`text-2xl font-display font-bold tracking-tight ${isScrolled ? 'text-[#1a3a34]' : 'text-white'}`}>LAND HUB</span>
        </div>

        <div className="hidden md:flex items-center gap-8">
          {['Home', 'Featured Plots', 'About Us', 'Why Us', 'Contact'].map((item) => (
            <a 
              key={item} 
              href={`#${item.toLowerCase().replace(' ', '-')}`}
              className={`text-sm font-medium hover:text-[#c5a059] transition-colors ${isScrolled ? 'text-gray-700' : 'text-white'}`}
            >
              {item}
            </a>
          ))}
          <button className={`px-6 py-2.5 rounded-full text-sm font-semibold transition-all hover:scale-105 active:scale-95 ${isScrolled ? 'bg-[#1a3a34] text-white' : 'bg-[#c5a059] text-white'}`}>
            Call Now
          </button>
        </div>

        <button className="md:hidden text-white" onClick={() => setMobileMenuOpen(true)}>
          <Menu className={isScrolled ? 'text-[#1a3a34]' : 'text-white'} />
        </button>
      </div>

      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div 
            initial={{ opacity: 0, x: '100%' }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: '100%' }}
            className="fixed inset-0 bg-white z-[60] flex flex-col p-8"
          >
            <div className="flex justify-between items-center mb-12">
              <span className="text-2xl font-display font-bold text-[#1a3a34]">LAND HUB</span>
              <button onClick={() => setMobileMenuOpen(false)}><X className="text-[#1a3a34]" /></button>
